   \"tsserver\": \"bin/tsserver\"\r\n      },\r\n      \"engines\": {\r\n        \"node\": \"\u003e=14.17\"\r\n      }\r\n    },\r\n    \"node_modules/undici-types\": {\r\n      \"version\": \"6.21.0\",\r\n      \"resolved\": \"https://registry.npmjs.org/undici-types/-/undici-types-6.21.0.tgz\",\r\n      \"integrity\": \"sha512-iwDZqg0QAGrg9Rav5H4n0M64c3mkR59cJ6wQp+7C4nI0gsmExaedaYLNO44eT4AtBBwjbTiGPMlt2Md0T9H9JQ==\",\r\n      \"dev\": true,\r\n      \"license\": \"MIT\"\r\n    },\r\n    \"node_modules/v8-compile-cache-lib\": {\r\n      \"version\": \"3.0.1\",\r\n      \"resolved\": \"https://registry.npmjs.org/v8-compile-cache-lib/-/v8-compile-cache-lib-3.0.1.tgz\",\r\n      \"integrity\": \"sha512-wa7YjyUGfNZngI/vtK0UHAN+lgDCxBPCylVXGp0zu59Fz5aiGtNXaq3DhIov063MorB+VfufLh3JlF2KdTK3xg==\",\r\n      \"dev\": true,\r\n      \"license\": \"MIT\"\r\n    },\r\n    \"node_modules/wsl-utils\": {\r\n      \"version\": \"0.1.0\",\r\n      \"resolved\": \"https://registry.npmjs.org/wsl-utils/-/wsl-utils-0.1.0.tgz\",\r\n      \"integrity\": \"sha512-h3Fbisa2nKGPxCpm89Hk33lBLsnaGBvctQopaBSOW/uIs6FTe1ATyAnKFJrzVs9vpGdsTe73WF3V4lIsk4Gacw==\",\r\n      \"license\": \"MIT\",\r\n      \"dependencies\": {\r\n        \"is-wsl\": \"^3.1.0\"\r\n      },\r\n      \"engines\": {\r\n        \"node\": \"\u003e=18\"\r\n      },\r\n      \"funding\": {\r\n        \"url\": \"https://github.com/sponsors/sindresorhus\"\r\n      }\r\n    },\r\n    \"node_modules/yn\": {\r\n      \"version\": \"3.1.1\",\r\n      \"resolved\": \"https://registry.npmjs.org/yn/-/yn-3.1.1.tgz\",\r\n      \"integrity\": \"sha512-Ux4ygGWsu2c7isFWe8Yu1YluJmqVhxqK2cLXNQA5AcC3QfbGNpM7fu0Y8b/z16pXLnFxZYvWhd3fhBY9DLmC6Q==\",\r\n      \"dev\": true,\r\n      \"license\": \"MIT\",\r\n      \"engines\": {\r\n        \"node\": \"\u003e=6\"\r\n      }\r\n    }\r\n  }\r\n}\r\n\n```\n\n### package.json\n```\n{\r\n  \"name\": \"azure-blob-storage-manager\",\r\n  \"version\": \"1.0.0\",\r\n  \"description\": \"Reusable Azure Blob Storage management utility with managed identity support\",\r\n  \"main\": \"dist/index.js\",\r\n  \"scripts\": {\r\n    \"build\": \"tsc\",\r\n    \"start\": \"node dist/index.js\",\r\n    \"dev\": \"ts-node src/index.ts\",\r\n    \"clean\": \"rm -rf dist\"\r\n  },\r\n  \"keywords\": [\r\n    \"azure\",\r\n    \"blob-storage\",\r\n    \"storage\",\r\n    \"typescript\"\r\n  ],\r\n  \"author\": \"\",\r\n  \"license\": \"MIT\",\r\n  \"dependencies\": {\r\n    \"@azure/storage-blob\": \"^12.18.0\",\r\n    \"@azure/identity\": \"^4.0.0\",\r\n    \"@azure/logger\": \"^1.0.4\"\r\n  },\r\n  \"devDependencies\": {\r\n    \"@types/node\": \"^20.10.0\",\r\n    \"typescript\": \"^5.3.0\",\r\n    \"ts-node\": \"^10.9.0\"\r\n  }\r\n}\r\n\n```\n\n### src\\blobService.ts\n```\nimport {\r\n  BlobServiceClient,\r\n  ContainerClient,\r\n  BlockBlobClient,\r\n  BlobUploadCommonResponse,\r\n  BlobDownloadResponseParsed,\r\n  BlobItem,\r\n  Tags,\r\n  Metadata\r\n} from '@azure/storage-blob';\r\nimport { Readable } from 'stream';\r\nimport * as fs from 'fs';\r\n\r\nexport interface UploadOptions {\r\n  metadata?: Metadata;\r\n  tags?: Tags;\r\n  contentType?: string;\r\n}\r\n\r\nexport interface LeaseInfo {\r\n  leaseId: string;\r\n  expiresAt: Date;\r\n}\r\n\r\nexport class BlobStorageService {\r\n  private containerClient: ContainerClient;\r\n\r\n  constructor(\r\n    private blobServiceClient: BlobServiceClient,\r\n    private containerName: string\r\n  ) {\r\n    this.containerClient = this.blobServiceClient.getContainerClient(containerName);\r\n  }\r\n\r\n  /**\r\n   * Ensures the container exists, creates it if it doesn't\r\n   */\r\n  async ensureContainer(): Promise\u003cvoid\u003e {\r\n    const exists = await this.containerClient.exists();\r\n    if (!exists) {\r\n      await this.containerClient.create();\r\n      console.log(`✓ Container '${this.containerName}' created`);\r\n    } else {\r\n      console.log(`✓ Container '${this.containerName}' already exists`);\r\n    }\r\n  }\r\n\r\n  /**\r\n   * Upload a file to blob storage using streaming for memory efficiency.\r\n   * Handles large files without loading them entirely into memory.\r\n   */\r\n  async uploadFile(\r\n    blobName: string,\r\n    filePath: string,\r\n    options?: UploadOptions\r\n  ): Promise\u003cBlobUploadCommonResponse\u003e {\r\n    const blockBlobClient = this.containerClient.getBlockBlobClient(blobName);\r\n    \r\n    // Create read stream for memory-efficient upload\r\n    const fileStream = fs.createReadStream(filePath);\r\n    const fileStats = fs.statSync(filePath);\r\n    \r\n    console.log(`⬆️  Uploading '${blobName}' (${this.formatBytes(fileStats.size)})...`);\r\n\r\n    const uploadResponse = await blockBlobClient.uploadStream(\r\n      fileStream,\r\n      4 * 1024 * 1024, // 4MB buffer size for streaming\r\n      5, // 5 concurrent uploads\r\n      {\r\n        blobHTTPHeaders: options?.contentType ? { blobContentType: options.contentType } : undefined,\r\n        metadata: options?.metadata,\r\n        tags: options?.tags\r\n      }\r\n    );\r\n\r\n    console.log(`✓ Upload complete. ETag: ${uploadResponse.etag}`);\r\n    return uploadResponse;\r\n  }\r\n\r\n  /**\r\n   * Upload from a stream (useful for in-memory data or piped content)\r\n   */\r\n  async uploadStream(\r\n    blobName: string,\r\n    stream: Readable,\r\n    options?: UploadOptions\r\n  ): Promise\u003cBlobUploadCommonResponse\u003e {\r\n    const blockBlobClient = this.containerClient.getBlockBlobClient(blobName);\r\n    \r\n    console.log(`⬆️  Uploading '${blobName}' from stream...`);\r\n\r\n    const uploadResponse = await blockBlobClient.uploadStream(\r\n      stream,\r\n      4 * 1024 * 1024,\r\n      5,\r\n      {\r\n        blobHTTPHeaders: options?.contentType ? { blobContentType: options.contentType } : undefined,\r\n        metadata: options?.metadata,\r\n        tags: options?.tags\r\n      }\r\n    );\r\n\r\n    console.log(`✓ Upload complete. ETag: ${uploadResponse.etag}`);\r\n    return uploadResponse;\r\n  }\r\n\r\n  /**\r\n   * Download a blob to a file\r\n   */\r\n  async downloadToFile(blobName: string, destinationPath: string): Promise\u003cvoid\u003e {\r\n    const blockBlobClient = this.containerClient.getBlockBlobClient(blobName);\r\n    \r\n    console.log(`⬇️  Downloading '${blobName}'...`);\r\n    \r\n    await blockBlobClient.downloadToFile(destinationPath);\r\n    \r\n    const fileStats = fs.statSync(destinationPath);\r\n    console.log(`✓ Download complete (${this.formatBytes(fileStats.size)})`);\r\n  }\r\n\r\n  /**\r\n   * Download blob content as a buffer\r\n   */\r\n  async downloadToBuffer(blobName: string): Promise\u003cBuffer\u003e {\r\n    const blockBlobClient = this.containerClient.getBlockBlobClient(blobName);\r\n    \r\n    console.log(`⬇️  Downloading '${blobName}' to memory...`);\r\n    \r\n    const downloadResponse = await blockBlobClient.download();\r\n    const chunks: Buffer[] = [];\r\n    \r\n    if (downloadResponse.readableStreamBody) {\r\n      for await (const chunk of downloadResponse.readableStreamBody) {\r\n        chunks.push(Buffer.from(chunk));\r\n      }\r\n    }\r\n    \r\n    const buffer = Buffer.concat(chunks);\r\n    console.log(`✓ Downloaded ${this.formatBytes(buffer.length)} to memory`);\r\n    return buffer;\r\n  }\r\n\r\n  /**\r\n   * List all blobs in the container with their metadata and tags\r\n   */\r\n  async listBlobs(): Promise\u003cBlobItem[]\u003e {\r\n    console.log(`📋 Listing blobs in container '${this.containerName}'...`);\r\n    \r\n    const blobs: BlobItem[] = [];\r\n    \r\n    // Include metadata and tags in the listing\r\n    for await (const blob of this.containerClient.listBlobsFlat({\r\n      includeMetadata: true,\r\n      includeTags: true\r\n    })) {\r\n      blobs.push(blob);\r\n    }\r\n    \r\n    console.log(`✓ Found ${blobs.length} blob(s)`);\r\n    return blobs;\r\n  }\r\n\r\n  /**\r\n   * Delete a blob\r\n   */\r\n  async deleteBlob(blobName: string): Promise\u003cvoid\u003e {\r\n    const blockBlobClient = this.containerClient.getBlockBlobClient(blobName);\r\n    \r\n    console.log(`🗑️  Deleting '${blobName}'...`);\r\n    \r\n    await blockBlobClient.delete();\r\n    \r\n    console.log(`✓ Blob deleted`);\r\n  }\r\n\r\n  /**\r\n   * Acquire a lease on a blob to prevent concurrent modifications.\r\n   * Returns the lease ID which must be provided for subsequent operations.\r\n   */\r\n  async acquireLease(blobName: string, durationSeconds: number = 60): Promise\u003cLeaseInfo\u003e {\r\n    const blockBlobClient = this.containerClient.getBlockBlobClient(blobName);\r\n    const blobLeaseClient = blockBlobClient.getBlobLeaseClient();\r\n    \r\n    console.log(`🔒 Acquiring ${durationSeconds}s lease on '${blobName}'...`);\r\n    \r\n    const leaseResponse = await blobLeaseClient.acquireLease(durationSeconds);\r\n    \r\n    const expiresAt = new Date(Date.now() + durationSeconds * 1000);\r\n    \r\n    console.log(`✓ Lease acquired. Lease ID: ${leaseResponse.leaseId}`);\r\n    console.log(`  Expires at: ${expiresAt.toISOString()}`);\r\n    \r\n    return {\r\n      leaseId: leaseResponse.leaseId!,\r\n      expiresAt\r\n    };\r\n  }\r\n\r\n  /**\r\n   * Release a lease on a blob\r\n   */\r\n  async releaseLease(blobName: string, leaseId: string): Promise\u003cvoid\u003e {\r\n    const blockBlobClient = this.containerClient.getBlockBlobClient(blobName);\r\n    const blobLeaseClient = blockBlobClient.getBlobLeaseClient(leaseId);\r\n    \r\n    console.log(`🔓 Releasing lease on '${blobName}'...`);\r\n    \r\n    await blobLeaseClient.releaseLease();\r\n    \r\n    console.log(`✓ Lease released`);\r\n  }\r\n\r\n  /**\r\n   * Upload with lease (prevents concurrent writes)\r\n   */\r\n  async uploadFileWithLease(\r\n    blobName: string,\r\n    filePath: string,\r\n    leaseId: string,\r\n    options?: UploadOptions\r\n  ): Promise\u003cBlobUploadCommonResponse\u003e {\r\n    const blockBlobClient = this.containerClient.getBlockBlobClient(blobName);\r\n    \r\n    const fileStream = fs.createReadStream(filePath);\r\n    const fileStats = fs.statSync(filePath);\r\n    \r\n    console.log(`⬆️  Uploading '${blobName}' with lease (${this.formatBytes(fileStats.size)})...`);\r\n\r\n    const uploadResponse = await blockBlobClient.uploadStream(\r\n      fileStream,\r\n      4 * 1024 * 1024,\r\n      5,\r\n      {\r\n        blobHTTPHeaders: options?.contentType ? { blobContentType: options.contentType } : undefined,\r\n        metadata: options?.metadata,\r\n        tags: options?.tags,\r\n        conditions: {\r\n          leaseId: leaseId\r\n        }\r\n      }\r\n    );\r\n\r\n    console.log(`✓ Upload with lease complete. ETag: ${uploadResponse.etag}`);\r\n    return uploadResponse;\r\n  }\r\n\r\n  /**\r\n   * Query blobs by index tags (requires Blob Index feature enabled on storage account)\r\n   */\r\n  async queryBlobsByTags(tagQuery: string): Promise\u003cstring[]\u003e {\r\n    console.log(`🔍 Querying blobs with tags: ${tagQuery}...`);\r\n    \r\n    const blobNames: string[] = [];\r\n    \r\n    const iterator = this.blobServiceClient.findBlobsByTags(tagQuery);\r\n    \r\n    for await (const blob of iterator) {\r\n      if (blob.containerName === this.containerName) {\r\n        blobNames.push(blob.name);\r\n      }\r\n    }\r\n    \r\n    console.log(`✓ Found ${blobNames.length} matching blob(s)`);\r\n    return blobNames;\r\n  }\r\n\r\n  private formatBytes(bytes: number): string {\r\n    if (bytes === 0) return '0 Bytes';\r\n    const k = 1024;\r\n    const sizes = ['Bytes', 'KB', 'MB', 'GB'];\r\n    const i = Math.floor(Math.log(bytes) / Math.log(k));\r\n    return Math.round(bytes / Math.pow(k, i) * 100) / 100 + ' ' + sizes[i];\r\n  }\r\n}\r\n\n```\n\n### src\\config.ts\n```\nimport { BlobServiceClient } from '@azure/storage-blob';\r\nimport { DefaultAzureCredential } from '@azure/identity';\r\nimport { setLogLevel, AzureLogger } from '@azure/logger';\r\n\r\nexport interface StorageConfig {\r\n  storageAccountEndpoint: string;\r\n  maxRetries?: number;\r\n  retryDelayMs?: number;\r\n  logLevel?: 'verbose' | 'info' | 'warning' | 'error';\r\n}\r\n\r\nexport class AzureStorageConfig {\r\n  private blobServiceClient: BlobServiceClient;\r\n  private config: Required\u003cStorageConfig\u003e;\r\n\r\n  constructor(config: StorageConfig) {\r\n    // Set defaults\r\n    this.config = {\r\n      storageAccountEndpoint: config.storageAccountEndpoint,\r\n      maxRetries: config.maxRetries ?? 3,\r\n      retryDelayMs: config.retryDelayMs ?? 1000,\r\n      logLevel: config.logLevel ?? 'info'\r\n    };\r\n\r\n    // Configure SDK logging\r\n    this.configureLogging(this.config.logLevel);\r\n\r\n    // Create BlobServiceClient with managed identity\r\n    const credential = new DefaultAzureCredential();\r\n    \r\n    this.blobServiceClient = new BlobServiceClient(\r\n      this.config.storageAccountEndpoint,\r\n      credential,\r\n      {\r\n        retryOptions: {\r\n          maxTries: this.config.maxRetries,\r\n          retryDelayInMs: this.config.retryDelayMs,\r\n          // Exponential backoff\r\n          maxRetryDelayInMs: this.config.retryDelayMs * Math.pow(2, this.config.maxRetries)\r\n        }\r\n      }\r\n    );\r\n\r\n    console.log(`✓ Azure Storage configured with managed identity`);\r\n    console.log(`  Endpoint: ${this.config.storageAccountEndpoint}`);\r\n    console.log(`  Max retries: ${this.config.maxRetries}`);\r\n    console.log(`  Retry delay: ${this.config.retryDelayMs}ms (exponential backoff)`);\r\n    console.log(`  Log level: ${this.config.logLevel}`);\r\n  }\r\n\r\n  private configureLogging(level: string): void {\r\n    // Map log levels to Azure SDK log levels\r\n    const logLevelMap: Record\u003cstring, any\u003e = {\r\n      'verbose': 'verbose',\r\n      'info': 'info',\r\n      'warning': 'warning',\r\n      'error': 'error'\r\n    };\r\n\r\n    setLogLevel(logLevelMap[level] || 'info');\r\n\r\n    // Set up logger to output to console\r\n    AzureLogger.log = (...args) =\u003e {\r\n      console.log('[Azure SDK]', ...args);\r\n    };\r\n  }\r\n\r\n  public getBlobServiceClient(): BlobServiceClient {\r\n    return this.blobServiceClient;\r\n  }\r\n\r\n  public getConfig(): Required\u003cStorageConfig\u003e {\r\n    return { ...this.config };\r\n  }\r\n}\r\n\r\n// Factory function to create configuration from environment\r\nexport function createStorageConfigFromEnv(): AzureStorageConfig {\r\n  const endpoint = process.env.AZURE_STORAGE_ENDPOINT;\r\n  \r\n  if (!endpoint) {\r\n    throw new Error('AZURE_STORAGE_ENDPOINT environment variable is required');\r\n  }\r\n\r\n  return new AzureStorageConfig({\r\n    storageAccountEndpoint: endpoint,\r\n    maxRetries: process.env.AZURE_STORAGE_MAX_RETRIES \r\n      ? parseInt(process.env.AZURE_STORAGE_MAX_RETRIES, 10) \r\n      : undefined,\r\n    retryDelayMs: process.env.AZURE_STORAGE_RETRY_DELAY_MS \r\n      ? parseInt(process.env.AZURE_STORAGE_RETRY_DELAY_MS, 10) \r\n      : undefined,\r\n    logLevel: (process.env.AZURE_STORAGE_LOG_LEVEL as any) || undefined\r\n  });\r\n}\r\n\n```\n\n### src\\index.ts\n```\nimport { createStorageConfigFromEnv } from './config';\r\nimport { BlobStorageService } from './blobService';\r\nimport * as fs from 'fs';\r\nimport * as path from 'path';\r\n\r\nasync function main() {\r\n  console.log('='.repeat(60));\r\n  console.log('Azure Blob Storage Management Demo');\r\n  console.log('='.repeat(60));\r\n  console.log();\r\n\r\n  try {\r\n    // Step 1: Initialize configuration with managed identity\r\n    console.log('📝 Step 1: Initializing Azure Storage configuration...');\r\n    const storageConfig = createStorageConfigFromEnv();\r\n    const blobServiceClient = storageConfig.getBlobServiceClient();\r\n    console.log();\r\n\r\n    // Step 2: Create service instance\r\n    const containerName = process.env.AZURE_STORAGE_CONTAINER || 'demo-container';\r\n    console.log(`📝 Step 2: Creating blob service for container '${containerName}'...`);\r\n    const blobService = new BlobStorageService(blobServiceClient, containerName);\r\n    \r\n    // Ensure container exists\r\n    await blobService.ensureContainer();\r\n    console.log();\r\n\r\n    // Step 3: Create a sample file to upload\r\n    console.log('📝 Step 3: Creating sample file...');\r\n    const sampleFileName = 'sample-data.txt';\r\n    const sampleFilePath = path.join(__dirname, '..', sampleFileName);\r\n    const sampleContent = `Azure Blob Storage Demo File\r\n=========================\r\n\r\nThis file demonstrates:\r\n- Streaming uploads for memory efficiency\r\n- Blob metadata and index tags\r\n- Lease-based concurrency control\r\n- Download and list operations\r\n\r\nGenerated at: ${new Date().toISOString()}\r\n\r\n`.repeat(1000); // Make it larger to demonstrate streaming\r\n\r\n    fs.writeFileSync(sampleFilePath, sampleContent);\r\n    const fileSize = fs.statSync(sampleFilePath).size;\r\n    console.log(`✓ Created sample file: ${sampleFileName} (${(fileSize / 1024).toFixed(2)} KB)`);\r\n    console.log();\r\n\r\n    // Step 4: Upload with metadata and tags\r\n    console.log('📝 Step 4: Uploading file with metadata and index tags...');\r\n    const blobName = `demo-${Date.now()}.txt`;\r\n    await blobService.uploadFile(blobName, sampleFilePath, {\r\n      metadata: {\r\n        uploadedBy: 'demo-script',\r\n        purpose: 'testing',\r\n        timestamp: new Date().toISOString()\r\n      },\r\n      tags: {\r\n        environment: 'development',\r\n        category: 'demo',\r\n        version: '1.0'\r\n      },\r\n      contentType: 'text/plain'\r\n    });\r\n    console.log();\r\n\r\n    // Step 5: List all blobs in container\r\n    console.log('📝 Step 5: Listing all blobs in container...');\r\n    const blobs = await blobService.listBlobs();\r\n    blobs.forEach((blob, index) =\u003e {\r\n      console.log(`\\n  Blob ${index + 1}:`);\r\n      console.log(`    Name: ${blob.name}`);\r\n      console.log(`    Size: ${(blob.properties.contentLength! / 1024).toFixed(2)} KB`);\r\n      console.log(`    Content Type: ${blob.properties.contentType}`);\r\n      console.log(`    Last Modified: ${blob.properties.lastModified}`);\r\n      \r\n      if (blob.metadata) {\r\n        console.log(`    Metadata:`, blob.metadata);\r\n      }\r\n      \r\n      if (blob.tags) {\r\n        console.log(`    Tags:`, blob.tags);\r\n      }\r\n    });\r\n    console.log();\r\n\r\n    // Step 6: Query blobs by tags\r\n    console.log('📝 Step 6: Querying blobs by tags...');\r\n    const matchingBlobs = await blobService.queryBlobsByTags(`environment='development' AND category='demo'`);\r\n    console.log(`  Matching blobs: ${matchingBlobs.join(', ')}`);\r\n    console.log();\r\n\r\n    // Step 7: Download the blob\r\n    console.log('📝 Step 7: Downloading blob...');\r\n    const downloadPath = path.join(__dirname, '..', 'downloaded-sample.txt');\r\n    await blobService.downloadToFile(blobName, downloadPath);\r\n    \r\n    // Read and display first few lines\r\n    const downloadedContent = fs.readFileSync(downloadPath, 'utf-8');\r\n    const previewLines = downloadedContent.split('\\n').slice(0, 10);\r\n    console.log(`\\n  Content preview (first 10 lines):`);\r\n    previewLines.forEach(line =\u003e console.log(`    ${line}`));\r\n    console.log(`    ... (${downloadedContent.split('\\n').length} total lines)`);\r\n    console.log();\r\n\r\n    // Step 8: Acquire lease and update blob\r\n    console.log('📝 Step 8: Acquiring lease and updating blob...');\r\n    const lease = await blobService.acquireLease(blobName, 60);\r\n    \r\n    // Create updated content\r\n    const updatedContent = `UPDATED FILE - ${new Date().toISOString()}\\n\\n${sampleContent}`;\r\n    const updatedFilePath = path.join(__dirname, '..', 'updated-sample.txt');\r\n    fs.writeFileSync(updatedFilePath, updatedContent);\r\n    \r\n    // Upload with lease (this prevents other writers from modifying)\r\n    await blobService.uploadFileWithLease(blobName, updatedFilePath, lease.leaseId, {\r\n      metadata: {\r\n        uploadedBy: 'demo-script',\r\n        purpose: 'testing-updated',\r\n        timestamp: new Date().toISOString(),\r\n        version: '2'\r\n      },\r\n      tags: {\r\n        environment: 'development',\r\n        category: 'demo',\r\n        version: '2.0',\r\n        updated: 'true'\r\n      },\r\n      contentType: 'text/plain'\r\n    });\r\n    \r\n    // Release the lease\r\n    await blobService.releaseLease(blobName, lease.leaseId);\r\n    console.log();\r\n\r\n    // Step 9: Verify update by downloading again\r\n    console.log('📝 Step 9: Verifying update...');\r\n    const verifyBuffer = await blobService.downloadToBuffer(blobName);\r\n    const verifyContent = verifyBuffer.toString('utf-8');\r\n    const firstLine = verifyContent.split('\\n')[0];\r\n    console.log(`  First line of updated blob: \"${firstLine}\"`);\r\n    console.log(`  ✓ Update verified!`);\r\n    console.log();\r\n\r\n    // Step 10: Clean up - delete the blob\r\n    console.log('📝 Step 10: Cleaning up...');\r\n    await blobService.deleteBlob(blobName);\r\n    \r\n    // Clean up local files\r\n    [sampleFilePath, downloadPath, updatedFilePath].forEach(file =\u003e {\r\n      if (fs.existsSync(file)) {\r\n        fs.unlinkSync(file);\r\n        console.log(`✓ Deleted local file: ${path.basename(file)}`);\r\n      }\r\n    });\r\n    console.log();\r\n\r\n    console.log('='.repeat(60));\r\n    console.log('✓ Demo completed successfully!');\r\n    console.log('='.repeat(60));\r\n\r\n  } catch (error) {\r\n    console.error('\\n❌ Error during demo:', error);\r\n    if (error instanceof Error) {\r\n      console.error(`   Message: ${error.message}`);\r\n      console.error(`   Stack: ${error.stack}`);\r\n    }\r\n    process.exit(1);\r\n  }\r\n}\r\n\r\n// Run the demo\r\nmain();\r\n\n```\n\n### tsconfig.json\n```\n{\r\n  \"compilerOptions\": {\r\n    \"target\": \"ES2020\",\r\n    \"module\": \"commonjs\",\r\n    \"lib\": [\"ES2020\"],\r\n    \"outDir\": \"./dist\",\r\n    \"rootDir\": \"./src\",\r\n    \"strict\": true,\r\n    \"esModuleInterop\": true,\r\n    \"skipLibCheck\": true,\r\n    \"forceConsistentCasingInFileNames\": true,\r\n    \"resolveJsonModule\": true,\r\n    \"moduleResolution\": \"node\",\r\n    \"declaration\": true,\r\n    \"declarationMap\": true,\r\n    \"sourceMap\": true\r\n  },\r\n  \"include\": [\"src/**/*\"],\r\n  \"exclude\": [\"node_modules\", \"dist\"]\r\n}\r\n\n```\n\n### QUICKSTART.md\n```\n# Quick Start Guide\r\n\r\n## Prerequisites\r\n\r\n1. **Azure Storage Account** with blob storage enabled\r\n2. **Authentication** set up (one of):\r\n   - Azure CLI: Run `az login` for local development\r\n   - Managed Identity: Enable on your Azure resource (App Service, VM, etc.)\r\n\r\n## Setup\r\n\r\n1. **Install dependencies**:\r\n   ```bash\r\n   npm install\r\n   ```\r\n\r\n2. **Configure environment variables**:\r\n   \r\n   Create a `.env` file (or set environment variables):\r\n   ```bash\r\n   AZURE_STORAGE_ENDPOINT=https://yourstorageaccount.blob.core.windows.net\r\n   AZURE_STORAGE_CONTAINER=demo-container\r\n   AZURE_STORAGE_LOG_LEVEL=info\r\n   ```\r\n\r\n   Replace `yourstorageaccount` with your actual storage account name.\r\n\r\n3. **Grant permissions** (if using Managed Identity):\r\n   \r\n   Assign the \"Storage Blob Data Contributor\" role to your managed identity:\r\n   ```bash\r\n   az role assignment create \\\r\n     --assignee \u003cmanaged-identity-principal-id\u003e \\\r\n     --role \"Storage Blob Data Contributor\" \\\r\n     --scope /subscriptions/\u003csub-id\u003e/resourceGroups/\u003crg\u003e/providers/Microsoft.Storage/storageAccounts/\u003cstorage-account\u003e\r\n   ```\r\n\r\n## Running the Demo\r\n\r\n### Development mode (with ts-node):\r\n```bash\r\nnpm run dev\r\n```\r\n\r\n### Production mode (compiled):\r\n```bash\r\nnpm run build\r\nnpm start\r\n```\r\n\r\n## What the Demo Does\r\n\r\nThe demo script (`src/index.ts`) performs the following operations:\r\n\r\n1. ✅ Initializes storage configuration with managed identity\r\n2. ✅ Creates/verifies container exists\r\n3. ✅ Generates a sample file (~200 KB)\r\n4. ✅ Uploads file with metadata and blob index tags\r\n5. ✅ Lists all blobs in the container\r\n6. ✅ Queries blobs by index tags\r\n7. ✅ Downloads the blob and displays content preview\r\n8. ✅ Acquires a 60-second lease on the blob\r\n9. ✅ Updates blob while holding the lease (prevents concurrent writes)\r\n10. ✅ Releases the lease\r\n11. ✅ Verifies the update by downloading again\r\n12. ✅ Deletes the blob and cleans up local files\r\n\r\n## Using the Library in Your Code\r\n\r\n```typescript\r\nimport { createStorageConfigFromEnv } from './config';\r\nimport { BlobStorageService } from './blobService';\r\n\r\n// Initialize\r\nconst config = createStorageConfigFromEnv();\r\nconst service = new BlobStorageService(\r\n  config.getBlobServiceClient(),\r\n  'my-container'\r\n);\r\n\r\n// Ensure container exists\r\nawait service.ensureContainer();\r\n\r\n// Upload a file\r\nawait service.uploadFile('myfile.txt', './local-file.txt', {\r\n  metadata: { source: 'upload-script' },\r\n  tags: { env: 'prod', version: '1.0' }\r\n});\r\n\r\n// List blobs\r\nconst blobs = await service.listBlobs();\r\n\r\n// Download\r\nawait service.downloadToFile('myfile.txt', './downloaded.txt');\r\n\r\n// Safe concurrent update with lease\r\nconst lease = await service.acquireLease('myfile.txt', 60);\r\nawait service.uploadFileWithLease('myfile.txt', './updated.txt', lease.leaseId);\r\nawait service.releaseLease('myfile.txt', lease.leaseId);\r\n\r\n// Delete\r\nawait service.deleteBlob('myfile.txt');\r\n```\r\n\r\n## Troubleshooting\r\n\r\n### Authentication Errors\r\n- **Local development**: Run `az login` and ensure you have access to the storage account\r\n- **Azure**: Verify Managed Identity is enabled and has the correct RBAC 